data.minimal_example:
GoogleOAuth2Client client = GoogleOAuth2Client(customUriScheme: 'my.test.app', redirectUri: 'my.test.app:/oauth2redirect');
OAuth2Helper oauth2Helper = OAuth2Helper(client, grantType: OAuth2Helper.authorizationCode, clientId: 'your_client_id', clientSecret: 'your_client_secret', scopes: ['https://www.googleapis.com/auth/drive.readonly']);
http.Response resp = await oauth2Helper.get('https://www.googleapis.com/drive/v3/files');
